mapper.update:
    	UPDATE
   			REP_REVEAL
		SET STATUS = 'D'
		WHERE
			1=1

			AND REP_ID = #{repId,jdbcType=VARCHAR}


			AND REPORT_NAME = #{reportName,jdbcType=VARCHAR}


			AND PRODID = #{prodid,jdbcType=VARCHAR}


			AND START_DATE = #{startDate,jdbcType=DATE}


			AND END_DATE = #{endDate,jdbcType=DATE}

		AND STATUS='E'

mapper.select:
    	SELECT  COUNT(1)
    	FROM	REP_REVEAL
    	WHERE
    			1=1

			AND REP_ID = #{repId,jdbcType=VARCHAR}


			AND REPORT_NAME = #{reportName,jdbcType=VARCHAR}


			AND PRODID = #{prodid,jdbcType=VARCHAR}


			AND START_DATE = #{startDate,jdbcType=DATE}


			AND END_DATE = #{endDate,jdbcType=DATE}

		AND STATUS='E'
		AND CONFIRM_STATUS='01'
